ValidationRule.errorConditionFormula:
IF( $UserRole.Name = "System Administrator", FALSE, AND( /* 只在 DR 流程觸發 */ OR( ISPICKVAL(Approval_Status__c,"Documents Required"), ISPICKVAL(PRIORVALUE(Approval_Status__c),"Documents Required") ),
/* ====== 避免與 S3 互斥：把 S3 的 5 / 6 / 7 交回 S3 判斷 ====== */
/* S3 Step 5：Reapplied|In Progress -> Reapplied|Documents Required （EHD）*/ NOT( AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "In Progress", TEXT(Status__c) = "Reapplied", TEXT(Approval_Status__c) = "Documents Required" ) ),
/* S3 Step 6：Reapplied|Documents Required -> Replied|Documents Required （RMS）*/ NOT( AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required", TEXT(Status__c) = "Replied", TEXT(Approval_Status__c) = "Documents Required" ) ),
/* S3 Step 7：Replied|Documents Required -> Reapplied|Documents Required / Closed|Documents Required （CC/B2B）*/ NOT( AND( TEXT(PRIORVALUE(Status__c)) = "Replied", TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required", OR( AND(TEXT(Status__c) = "Reapplied", TEXT(Approval_Status__c) = "Documents Required"), AND(TEXT(Status__c) = "Closed", TEXT(Approval_Status__c) = "Documents Required") ) ) ), /* 交回 S3：Reapplied|DR -> Reapplied|Approved / Conditionally Approved / Rejected （EHD）*/ NOT( AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required", TEXT(Status__c) = "Reapplied", OR( TEXT(Approval_Status__c) = "Approved", TEXT(Approval_Status__c) = "Conditionally Approved", TEXT(Approval_Status__c) = "Rejected" ) ) ),
/* ====== S5 自身白名單檢查 ====== */ OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)), NOT( CONTAINS( ";" & /* S5 合法轉換清單（維持你原本內容） */ "New|New>In Progress|New;" & "In Progress|New>In Progress|In Progress;" & "In Progress|In Progress>In Progress|Documents Required;" & "In Progress|Documents Required>Replied|Documents Required;" & "Replied|Documents Required>Reapplied|Documents Required;" & "Replied|Documents Required>Closed|Documents Required;" & "Reapplied|Documents Required>Reapplied|In Progress;" & "Reapplied|In Progress>Reapplied|Approved;" & "Reapplied|In Progress>Reapplied|Conditionally Approved;" & "Reapplied|In Progress>Reapplied|Rejected;" & "Reapplied|Approved>Replied|Approved;" & "Reapplied|Conditionally Approved>Replied|Conditionally Approved;" & "Reapplied|Rejected>Replied|Rejected;" & "Replied|Approved>Closed|Approved;" & "Replied|Conditionally Approved>Closed|Conditionally Approved;" & "Replied|Rejected>Closed|Rejected;" & ";", ";" & TEXT(PRIORVALUE(Status__c)) & "|" & TEXT(PRIORVALUE(Approval_Status__c)) & ">" & TEXT(Status__c) & "|" & TEXT(Approval_Status__c) & ";" ) ) ) )
